using System.Text.Json;
using WorkflowDelivery.Platform;
using WorkflowDelivery.Repository;

namespace WorkflowDelivery.Tests.Repository;

// Contract tests that run the mise-locked PNPM through the application's own readers against
// a committed fixture workspace and lock (fixtures/pnpm-contract, generated by the pinned PNPM
// with install --lockfile-only --offline --ignore-scripts). The Linux native-preparation job
// runs them under mise exec --locked; a PNPM or Node pin change that alters a consumed fact
// fails here. Every query is lockfile-only: no install, script, registry or store access.
[TestClass]
[TestCategory("PnpmNativeContract")]
public sealed class PnpmGraphContractTests(TestContext context)
{
    private const string Publisher = "members/publisher";
    private static readonly string[] Members = [".", "members/alias", "members/app",
        "members/core", "members/cycle-a", "members/cycle-b", "members/dir-consumer",
        "members/file-consumer", "members/link-consumer", "members/outer",
        "members/outer/inner", "members/peer-consumer", "members/peer-lib", Publisher,
        "members/tarball-consumer", "members/top", "members/unrelated"];
    private static readonly string[] TopClosure = ["members/app", "members/core",
        "members/top"];
    private static readonly string[] OuterClosure = ["members/outer"];
    private static readonly string[] HookCandidates = [".pnpmfile.mjs", ".pnpmfile.cjs",
        ".pnpmfile.js", ".pnpmfile.ts", ".pnpmfile.mts", ".pnpmfile.cts", "pnpmfile.mjs",
        "pnpmfile.cjs", "pnpmfile.js"];

    // The complete projection the planner consumes: every member, its native dependency
    // closure through link, workspace alias, optional, dev, transitive, cycle, injected-peer
    // and file:/link: publish-directory edges, publish coordinates and non-member inputs.
    [TestMethod]
    [OSCondition(OperatingSystems.Linux)]
    public async Task GraphReaderProjectsTheFixtureWorkspaceExactly()
    {
        using var tool = await PnpmNativeTool.CreateAsync(context.CancellationToken);
        using var copy = new FixtureCopy("pnpm-contract");

        PnpmGraph graph = await Reader(tool, copy.Root).ReadAsync(context.CancellationToken);

        CollectionAssert.AreEqual(Members, graph.Projects.Select(project => project.Directory)
            .ToArray());
        Assert.AreEqual(Expected, string.Join("\n", graph.Projects.Select(project =>
            project.Directory + " <" + project.Name + "> [" + string.Join(",",
                project.Dependencies) + "]" + (project.PublishDirectory is { } output
                    ? " publish=" + output : ""))));
        Assert.AreEqual("vendor/archived-1.0.0.tgz file members/tarball-consumer\n" +
            "vendor/plain directory members/dir-consumer", string.Join("\n",
                graph.LocalInputs.OrderBy(input => input.Path, StringComparer.Ordinal).Select(
                    input => input.Path + (input.IsDirectory ? " directory " : " file ") +
                        string.Join(",", input.Consumers))));
    }

    private const string Expected = """
        . <@contract/root> []
        members/alias <@contract/alias> [members/core]
        members/app <@contract/app> [members/core]
        members/core <@contract/core> []
        members/cycle-a <@contract/cycle-a> [members/cycle-b]
        members/cycle-b <@contract/cycle-b> [members/cycle-a]
        members/dir-consumer <@contract/dir-consumer> []
        members/file-consumer <@contract/file-consumer> [members/publisher]
        members/link-consumer <@contract/link-consumer> [members/publisher]
        members/outer <@contract/outer> []
        members/outer/inner <@contract/inner> [members/core]
        members/peer-consumer <@contract/peer-consumer> [members/core,members/peer-lib]
        members/peer-lib <@contract/peer-lib> [members/core]
        members/publisher <@contract/publisher> [] publish=members/publisher/dist output
        members/tarball-consumer <@contract/tarball-consumer> []
        members/top <@contract/top> [members/app,members/core]
        members/unrelated <@contract/unrelated> []
        """;

    // The closure query the reader issues: with legacy directory filtering off, a directory
    // selector selects that project and its dependencies only, never nested projects.
    [TestMethod]
    [OSCondition(OperatingSystems.Linux)]
    [DataRow("members/top", "top")]
    [DataRow("members/outer", "outer")]
    public async Task DirectorySelectorClosureIsExact(string directory, string expected)
    {
        using var tool = await PnpmNativeTool.CreateAsync(context.CancellationToken);
        using var copy = new FixtureCopy("pnpm-contract");

        string answer = await tool.QueryAsync(copy.Root, ["--config.legacy-dir-filtering=false",
            "--filter", "{./" + directory + "}...", "list", "--recursive",
            "--include-workspace-root", "--lockfile-only", "--json", "--depth", "-1"],
            context.CancellationToken);

        using JsonDocument closure = JsonDocument.Parse(answer);
        CollectionAssert.AreEqual(expected == "top" ? TopClosure : OuterClosure,
            closure.RootElement.EnumerateArray().Select(project => Path.GetRelativePath(
                copy.Root, project.GetProperty("path").GetString()!).Replace('\\', '/'))
                .Order(StringComparer.Ordinal).ToArray());
    }

    // Script metadata: an object of strings for a member that declares scripts, empty
    // output for one that does not.
    [TestMethod]
    [OSCondition(OperatingSystems.Linux)]
    public async Task ScriptReaderReturnsDeclaredScriptsOrNone()
    {
        using var tool = await PnpmNativeTool.CreateAsync(context.CancellationToken);
        using var copy = new FixtureCopy("pnpm-contract");
        var reader = new PnpmScriptReader(copy.Root, (arguments, token) =>
            tool.QueryAsync(copy.Root, arguments, token));

        PnpmScripts core = await reader.ReadAsync(new("members/core", null, []),
            context.CancellationToken);
        PnpmScripts app = await reader.ReadAsync(new("members/app", null, []),
            context.CancellationToken);

        KeyValuePair<string, string> script = Assert.ContainsSingle(core.Scripts);
        Assert.AreEqual(("test", "node --test"), (script.Key, script.Value));
        Assert.IsEmpty(app.Scripts);
    }

    // Settings the reader guards are read from the workspace through config get; each one
    // set on the workspace stops planning, and the committed fixture plans.
    [TestMethod]
    [OSCondition(OperatingSystems.Linux)]
    [DataRow("none")]
    [DataRow("dedicated-lock")]
    [DataRow("relocated-lock")]
    [DataRow("pnpmfile")]
    [DataRow("config-dependencies")]
    [DataRow("hoisted-linker")]
    [DataRow("global-pnpmfile")]
    public async Task GuardedWorkspaceSettingsStopPlanning(string setting)
    {
        using var tool = await PnpmNativeTool.CreateAsync(context.CancellationToken);
        using var copy = new FixtureCopy("pnpm-contract");
        string workspace = Path.Combine(copy.Root, "pnpm-workspace.yaml");
        string extra = setting switch
        {
            "dedicated-lock" => "sharedWorkspaceLockfile: false\n",
            "pnpmfile" => "pnpmfile: hooks/settings.cjs\n",
            "config-dependencies" => "configDependencies:\n  probe: 1.0.0+sha512-AAAA\n",
            "hoisted-linker" => "nodeLinker: hoisted\n",
            _ => "",
        };
        File.AppendAllText(workspace, extra);
        if (setting == "global-pnpmfile")
            tool.Extra["PNPM_CONFIG_GLOBAL_PNPMFILE"] = Path.Combine(copy.Root, "global.cjs");
        if (setting == "relocated-lock")
            tool.Extra["PNPM_CONFIG_LOCKFILE_DIR"] = Path.Combine(copy.Scratch, "elsewhere");

        Task<PnpmGraph> read = Reader(tool, copy.Root).ReadAsync(context.CancellationToken);

        if (setting == "none")
            Assert.HasCount(Members.Length, (await read).Projects);
        else
            await Assert.ThrowsExactlyAsync<InvalidDataException>(() => read);
    }

    // A default pnpmfile is loaded without any setting; config get cannot see it. Every hook
    // file name the pinned PNPM loads must be one the repository reader rejects, and the hook
    // is observable: it narrows the reader's membership query.
    [TestMethod]
    [OSCondition(OperatingSystems.Linux)]
    public async Task EveryDefaultHookFilePnpmLoadsIsRejectedByTheReader()
    {
        using var tool = await PnpmNativeTool.CreateAsync(context.CancellationToken);
        var loaded = new List<string>();
        foreach (string name in HookCandidates)
        {
            using var copy = new FixtureCopy("pnpm-contract");
            string hook = "updateConfig(config) { return { ...config, " +
                "filter: ['{./members/core}'] }; }";
            File.WriteAllText(Path.Combine(copy.Root, name), name.EndsWith(".mjs",
                StringComparison.Ordinal) || name.EndsWith(".mts", StringComparison.Ordinal)
                ? "export const hooks = { " + hook + " };\n"
                : "module.exports = { hooks: { " + hook + " } };\n");
            NativeCommandResult result = await tool.RunAsync("pnpm", copy.Root, ["list",
                "--recursive", "--include-workspace-root", "--lockfile-only", "--json",
                "--depth", "-1"], context.CancellationToken);
            PnpmNativeTool.AssertExited(result, true);
            using JsonDocument membership = JsonDocument.Parse(result.Stdout);
            int count = membership.RootElement.GetArrayLength();
            Assert.IsTrue(count == 1 || count == Members.Length, name + ": " + count);
            if (count == 1) loaded.Add(name);
        }

        context.WriteLine("Loaded hook files: " + string.Join(", ", loaded));
        Assert.Contains(".pnpmfile.mjs", loaded);
        foreach (string name in loaded)
            Assert.Contains(name, NodeRepositoryReader.HookFiles);
    }

    private static PnpmGraphReader Reader(PnpmNativeTool tool, string root) =>
        new(root, (arguments, token) => tool.QueryAsync(root, arguments, token));

    // A disposable fixture copy under a path with a space, outside any Git checkout.
    internal sealed class FixtureCopy : IDisposable
    {
        internal string Scratch { get; } = Directory.CreateTempSubdirectory(
            "pnpm-contract-").FullName;
        internal string Root { get; }

        internal FixtureCopy(string fixture) => Root = PnpmNativeTool.Copy(fixture,
            Path.Combine(Scratch, "fixture workspace"));

        public void Dispose() => ScratchRoots.TryDelete(Scratch);
    }
}
